, H1 west -> SW, H2 east -> NE\n  A.SLOT_TOWER = {T1 = \"BIG_NW\", T2 = \"BIG_SE\", R1 = \"SM_NW\", R2 = \"SM_NE\", M1 = \"SM_SW\", M2 = \"SM_SE\", H1 = \"SM_SW\", H2 = \"SM_NE\"}\n  A.CFG_PATH = GetLuaModsPath() .. [[TensorReactions\\ArkveldEX_settings.lua]]\n  local cfg = {tower = \"AUTO\", lcArrows = true, towerArrows = true, countdown = true}\n  if FileExists and FileExists(A.CFG_PATH) then\n    local ok, saved = pcall(FileLoad, A.CFG_PATH)\n    if ok and type(saved) == \"table\" then\n      for k, v in pairs(saved) do\n        if cfg[k] ~= nil and type(v) == type(cfg[k]) then cfg[k] = v end\n      end\n    end\n  end\n  if not (cfg.tower == \"AUTO\" or cfg.tower == \"NONE\" or A.TDIR[cfg.tower]) then\n    cfg.tower = A.SLOT_TOWER[cfg.tower] or \"AUTO\"\n  end\n  A.cfg = cfg\n  -- puddle countdown: {from, to (s after the tower cast), colour}; the last one is the tower soak\n  A.TW_STEP = {{0, 3.0, 0xFFFFFFFF}, {3.0, 5.55, 0xFFFFFFFF}, {5.55, 8.03, 0xFFFFFFFF}, {8.03, 10.97, 0xFF33FF33}}\n  function A.saveCfg()\n    local ok = pcall(FileSave, A.CFG_PATH, A.cfg)\n    A.cfgMsg = ok and \"Saved.\" or \"Save failed!\"\n  end\n  -- my slot from AnyoneCore's Party Roster (T1 T2 H1 H2 M1 M2 R1 R2), nil if the roster is not set\n  function A.slot()\n    local R = AnyoneCore and AnyoneCore.Roster\n    if not (R and R.mySlot) then return nil end\n    local ok, s = pcall(R.mySlot)\n    return ok and s or nil\n  end\n  -- role letter T/H/M/R from the roster slot, else from the job\n  A.JOBROLE = {[1]=\"T\",[3]=\"T\",[19]=\"T\",[21]=\"T\",[32]=\"T\",[37]=\"T\", [6]=\"H\",[24]=\"H\",[28]=\"H\",[33]=\"H\",[40]=\"H\",\n               [2]=\"M\",[4]=\"M\",[20]=\"M\",[22]=\"M\",[29]=\"M\",[30]=\"M\",[34]=\"M\",[39]=\"M\",[41]=\"M\",\n               [5]=\"R\",[7]=\"R\",[23]=\"R\",[25]=\"R\",[26]=\"R\",[27]=\"R\",[31]=\"R\",[35]=\"R\",[38]=\"R\",[42]=\"R\"}\n  function A.role()\n    local s = A.slot()\n    if s then return s:sub(1, 1) end\n    local p = TensorCore.mGetPlayer()\n    return p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Rush (Devour): yellow = wait just outside the 3rd landing by the wall; green = step into the 3rd circle\n-- once it has gone off (tanks/melee next to the boss, healers/ranged back by the wall).\n-- Before dash 1 (boss start -> landing 1, 12 wide) goes off: if walking straight to the wait spot would still\n-- have you in it when it goes off, the yellow arrow first points to a hold spot just outside it on your own side.\nlocal M = A.m_rush\nif not (M and M.W and not M.over) then return end\nlocal tt = (Now() - M.t) / 1000\nif tt < 0 or tt > M.tEnd then return end\nif M.c3 or tt >= M.tC + 0.35 then\n  local F = A.close() and M.Fc or M.Ff\n  A.ring(M.l3x, M.l3z, 8, 0x33FF33)\n  A.goTo(F[1], F[2], 0x33FF33, 1.0)\n  return\nend\nlocal wx, wz = M.W[1], M.W[2]\nif not M.d1done and tt < 6.36 and M.dsx then\n  local p = TensorCore.mGetPlayer()\n  if p and p.pos then\n    local px, pz = p.pos.x, p.pos.z\n    local sx, sz, ex, ez = M.dsx, M.dsz, M.L[1].x, M.L[1].z\n    local ax, az = ex - sx, ez - sz\n    local ln = math.max(0.1, math.sqrt(ax * ax + az * az))\n    ax, az = ax / ln, az / ln\n    -- distance outside the dash rect (half width 6) of point (qx, qz)\n    local function out(qx, qz)\n      local vx, vz = qx - sx, qz - sz\n      local al = vx * ax + vz * az\n      local pp = math.abs(vx * az - vz * ax)\n      if al >= 0 and al <= ln then return pp - 6 end\n      local e = al < 0 and -al or al - ln\n      if pp > 6 then return math.sqrt((pp - 6) ^ 2 + e * e) end\n      return e\n    end\n    local rem = 6 * math.max(0, 5.81 - tt)   -- metres you can still walk before it goes off (0.3 s reaction)\n    local function at(tx, tz)\n      local dx, dz = tx - px, tz - pz\n      local d = math.sqrt(dx * dx + dz * dz)\n      if d < 0.01 then return px, pz end\n      local s = math.min(d, rem)\n      return px + dx / d * s, pz + dz / d * s\n    end\n    if not M.hOn then\n      local qx, qz = at(wx, wz)\n      if out(qx, qz) < 2.0 then\n        local pp = (px - sx) * az - (pz - sz) * ax\n        if math.abs(pp) < 0.5 then pp = (wx - sx) * az - (wz - sz) * ax end\n        M.hOn, M.hSg = true, (pp > 0 and 1 or -1)\n      end\n    end\n    if M.hOn then\n      local sg = M.hSg\n      local bx, bz, bd\n      for i = 0, math.floor(ln) do\n        local hx, hz = sx + i * ax + sg * 8 * az, sz + i * az - sg * 8 * ax\n        if (hx - A.CX) ^ 2 + (hz - A.CZ) ^ 2 <= 342.25 then\n          local qx, qz = at(hx, hz)\n          if out(qx, qz) >= 1.5 then\n            local dw = (hx - wx) ^ 2 + (hz - wz) ^ 2\n            if not bd or dw < bd then bx, bz, bd = hx, hz, dw end\n          end\n        end\n      end\n      if not bx then\n        local al = math.min(math.max((px - sx) * ax + (pz - sz) * az, 0), ln)\n        bx, bz = sx + al * ax + sg * 8 * az, sz + al * az - sg * 8 * ax\n      end\n      A.goTo(bx, bz, 0x00FFFF, 1.0)\n      return\n    end\n  end\nend\nA.goTo(wx, wz, 0x00FFFF, 1.0)\n",
