eturn p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Steeltail / Chainblade Charge: resolutions.\n-- 44805 / 44806 tail line hit, 43948 boss->stack target (fallback for the marker), 44812 stack hit\n-- (Cast Pos = stack spot = centre of the big puddle), 43933 big puddle hit.\nlocal e = eventArgs\nif not e then self.used = true return end\nlocal id = tonumber(e.spellID)\nlocal M = A.m_tail\nif not M or not (id == 44805 or id == 44806 or id == 43948 or id == 44812 or id == 43933) then\n  self.used = true return\nend\nlocal now = Now()\nif id == 44805 or id == 44806 then\n  if M.tT and now - M.tT < 8000 then M.tDone = now end\nelseif id == 43948 then\n  if M.cT and now - M.cT < 10000 and not M.cTgt then M.cTgt = e.targetID end\nelseif id == 44812 then\n  if M.cT and now - M.cT < 12000 then\n    local x, z = tonumber(e.castPosX), tonumber(e.castPosZ)\n    if not x or not z or (x == 0 and z == 0) then\n      local t = M.cTgt and TensorCore.mGetEntity(M.cTgt)\n      if t and t.pos then x, z = t.pos.x, t.pos.z else x, z = nil, nil end\n    end\n    if x and z then M.hitT = now; M.sx, M.sz = x, z end\n  end\nelseif id == 43933 then\n  M.pudDone = now\nend\nself.used = true\n",
