eturn p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Limit cut: arrow to where your number has to be right now.\n-- 43955: #1/#5 boss-left (E), #2/#6 boss-front (S), #3/#7 boss-right (W), #4/#8 behind the boss (N). 43958 mirrors E/W.\n-- #1-#3 go out at once, #4 waits inside north until cleave 1, #5-#8 wait mid and go out after cleave (n-3).\n-- After your own jump: back to the middle until your cleave has gone off.\nlocal L, n = A.lc, A.lcN\nif not (A.cfg.lcArrows and L and n and A.lcNT and math.abs(A.lcNT - L.t) < 3000) then return end\nlocal tt = (Now() - L.t) / 1000\nif tt > 36 then return end\n-- jump / cleave counts from the events; if an event is missed, step on 0.8 s after it was due\nlocal function fb(cnt, lastT, first)\n  local base = (cnt > 0 and lastT) and (lastT - L.t) / 1000 or (first - 3.07)\n  local over = tt - base - 3.07 - 0.8\n  if over < 0 then return cnt end\n  return math.min(8, cnt + math.floor(over / 3.07) + 1)\nend\nlocal j = fb(L.j, L.jT[L.j], 8.05)\nlocal c = fb(L.c, L.c > 0 and L.lastC or nil, 10.1)\nlocal fx, fz = math.sin(L.h), math.cos(L.h)    -- boss forward\nlocal lx, lz = math.cos(L.h), -math.sin(L.h)   -- boss left\nlocal sx, sz = lx, lz\nif not L.cw then sx, sz = -lx, -lz end\nlocal k = (n - 1) % 4 + 1\nlocal dx, dz\nif k == 1 then dx, dz = sx, sz elseif k == 2 then dx, dz = fx, fz elseif k == 3 then dx, dz = -sx, -sz else dx, dz = -fx, -fz end\nlocal R = 18.5\nif j >= n then\n  -- jumped: back to the middle, until your own cleave has resolved\n  if c >= n then return end\n  A.goTo(A.CX, A.CZ, 0x33FF33, 1.5)\n  return\nend\n-- #5-#8 leave the middle after cleave (n-3): the cleave right after #(n-4)'s runs through that spot\nlocal ready = (n <= 3) or (n == 4 and c >= 1) or (n >= 5 and c >= n - 3)\nif ready then\n  A.goTo(A.CX + R * dx, A.CZ + R * dz, 0x33FF33, 1.0)\nelseif n == 4 then\n  A.goTo(A.CX + 8 * dx, A.CZ + 8 * dz, 0x00FFFF, 1.0)   -- wait inside north\nelse\n  A.goTo(A.CX, A.CZ, 0x00FFFF, 1.5)                     -- wait mid\nend\n",
