, H1 west -> SW, H2 east -> NE\n  A.SLOT_TOWER = {T1 = \"BIG_NW\", T2 = \"BIG_SE\", R1 = \"SM_NW\", R2 = \"SM_NE\", M1 = \"SM_SW\", M2 = \"SM_SE\", H1 = \"SM_SW\", H2 = \"SM_NE\"}\n  A.CFG_PATH = GetLuaModsPath() .. [[TensorReactions\\ArkveldEX_settings.lua]]\n  local cfg = {tower = \"AUTO\", lcArrows = true, towerArrows = true, countdown = true}\n  if FileExists and FileExists(A.CFG_PATH) then\n    local ok, saved = pcall(FileLoad, A.CFG_PATH)\n    if ok and type(saved) == \"table\" then\n      for k, v in pairs(saved) do\n        if cfg[k] ~= nil and type(v) == type(cfg[k]) then cfg[k] = v end\n      end\n    end\n  end\n  if not (cfg.tower == \"AUTO\" or cfg.tower == \"NONE\" or A.TDIR[cfg.tower]) then\n    cfg.tower = A.SLOT_TOWER[cfg.tower] or \"AUTO\"\n  end\n  A.cfg = cfg\n  -- puddle countdown: {from, to (s after the tower cast), colour}; the last one is the tower soak\n  A.TW_STEP = {{0, 3.0, 0xFFFFFFFF}, {3.0, 5.55, 0xFFFFFFFF}, {5.55, 8.03, 0xFFFFFFFF}, {8.03, 10.97, 0xFF33FF33}}\n  function A.saveCfg()\n    local ok = pcall(FileSave, A.CFG_PATH, A.cfg)\n    A.cfgMsg = ok and \"Saved.\" or \"Save failed!\"\n  end\n  -- my slot from AnyoneCore's Party Roster (T1 T2 H1 H2 M1 M2 R1 R2), nil if the roster is not set\n  function A.slot()\n    local R = AnyoneCore and AnyoneCore.Roster\n    if not (R and R.mySlot) then return nil end\n    local ok, s = pcall(R.mySlot)\n    return ok and s or nil\n  end\n  -- role letter T/H/M/R from the roster slot, else from the job\n  A.JOBROLE = {[1]=\"T\",[3]=\"T\",[19]=\"T\",[21]=\"T\",[32]=\"T\",[37]=\"T\", [6]=\"H\",[24]=\"H\",[28]=\"H\",[33]=\"H\",[40]=\"H\",\n               [2]=\"M\",[4]=\"M\",[20]=\"M\",[22]=\"M\",[29]=\"M\",[30]=\"M\",[34]=\"M\",[39]=\"M\",[41]=\"M\",\n               [5]=\"R\",[7]=\"R\",[23]=\"R\",[25]=\"R\",[26]=\"R\",[27]=\"R\",[31]=\"R\",[35]=\"R\",[38]=\"R\",[42]=\"R\"}\n  function A.role()\n    local s = A.slot()\n    if s then return s:sub(1, 1) end\n    local p = TensorCore.mGetPlayer()\n    return p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Wyvern's Ouroblade: arrow to your own spread spot in the safe half (spread r6, all 8 players).\n-- Spots: angle from the safe direction toward the boss's FRONT (deg), distance from the boss centre (y).\n-- Inner ring 10y (tanks + melee, in melee range: autos land up to ~11y from the centre), outer ring 18y (healers + ranged).\n-- Inner spots 50deg apart (8.45y), every pair >= 8.0y apart (spread is 6y), closest spot 2.6y clear of the cleave edge.\nlocal M = A.m_ouroblade\nif not (M and M.t) then return end\nlocal el = Now() - M.t\nif el > M.dur + 1300 or (M.done and Now() > M.done) then return end\nif not M.h then\n  local en = M.id and TensorCore.mGetEntity(M.id)\n  if not (en and en.pos and en.pos.h) then return end\n  M.h, M.cx, M.cz = en.pos.h, en.pos.x, en.pos.z\nend\nlocal S = A.OURO_SPOT2\nif not S then\n  S = {T1 = {10, 75}, T2 = {10, 25}, M1 = {10, -25}, M2 = {10, -75},\n       H1 = {18, 67.5}, R1 = {18, 22.5}, R2 = {18, -22.5}, H2 = {18, -67.5}}\n  A.OURO_SPOT2 = S\n  A.OURO_PAIR = {T = {\"T1\", \"T2\"}, M = {\"M1\", \"M2\"}, H = {\"H1\", \"H2\"}, R = {\"R1\", \"R2\"}}\n  A.OURO_ORDER = {\"T1\", \"T2\", \"M1\", \"M2\", \"H1\", \"H2\", \"R1\", \"R2\"}\nend\nlocal sa = M.h - M.sg * math.pi / 2          -- safe direction (away from the cleave)\nif not M.key then\n  local k = A.slot()\n  if not (k and S[k]) then\n    -- no Party Roster: same-role party members split the role's two spots by entity id (lowest id = spot 1),\n    -- extra members of a role take the free spots in order; solo / no party list = nearer spot of your role\n    k = nil\n    local p = TensorCore.mGetPlayer()\n    local role = A.role()\n    local pr = A.OURO_PAIR[role or \"\"]\n    if not (pr and p and p.pos) then return end\n    local ok, L = pcall(EntityList, \"myparty\")\n    if ok and type(L) == \"table\" then\n      local byRole, seen = {T = {}, M = {}, H = {}, R = {}}, {[p.id] = true}\n      byRole[role][1] = p.id\n      for _, e in pairs(L) do\n        local r = e and e.id and A.JOBROLE[e.job]\n        if r and not seen[e.id] then seen[e.id] = true; table.insert(byRole[r], e.id) end\n      end\n      if #byRole[role] > 1 then\n        local used, extra = {}, {}\n        for _, r in ipairs({\"T\", \"M\", \"H\", \"R\"}) do\n          local ids = byRole[r]\n          table.sort(ids)\n          for i, id in ipairs(ids) do\n            if i <= 2 then used[A.OURO_PAIR[r][i]] = id else extra[#extra + 1] = id end\n          end\n        end\n        for i, id in ipairs(byRole[role]) do\n          if id == p.id and i <= 2 then k = pr[i] end\n        end\n        if not k then\n          table.sort(extra)\n          local n = 0\n          for _, id in ipairs(extra) do\n            n = n + 1\n            if id == p.id then\n              local c = 0\n              for _, s in ipairs(A.OURO_ORDER) do\n                if not used[s] then c = c + 1; if c == n then k = s end end\n              end\n            end\n          end\n        end\n      end\n    end\n    if not k then\n      local bd\n      for _, c in ipairs(pr) do\n        local a = sa + M.sg * math.rad(S[c][2])\n        local d = (M.cx + S[c][1] * math.sin(a) - p.pos.x) ^ 2 + (M.cz + S[c][1] * math.cos(a) - p.pos.z) ^ 2\n        if not bd or d < bd then bd, k = d, c end\n      end\n    end\n  end\n  M.key = k\nend\nlocal s = S[M.key]\nif not s then return end\nlocal a = sa + M.sg * math.rad(s[2])\nA.goTo(M.cx + s[1] * math.sin(a), M.cz + s[1] * math.cos(a), 0x33FF33, 1.0)\n",
