eturn p and A.JOBROLE[p.job] or nil\n  end\n  -- melee uptime roles (tanks + melee) stay close to the boss where the strat allows it\n  function A.close()\n    local r = A.role()\n    return r == \"T\" or r == \"M\"\n  end\n  -- light parties HTMM / HTRR: 1 = T1 H1 M1 M2 (close to the boss), 2 = T2 H2 R1 R2; nil if unknown\n  A.SLOT_LP = {T1 = 1, H1 = 1, M1 = 1, M2 = 1, T2 = 2, H2 = 2, R1 = 2, R2 = 2}\n  function A.lp()\n    local s = A.slot()\n    if s then return A.SLOT_LP[s] end\n    local r = A.role()\n    if r == \"M\" then return 1 elseif r == \"R\" then return 2 end\n    return nil\n  end\n  -- entity list: the global EntityList (used by other profiles here) first, TensorCore.entityList as a fallback\n  function A.ents(f)\n    if EntityList then local ok, l = pcall(EntityList, f) if ok and type(l) == \"table\" then return l end end\n    if TensorCore.entityList then local ok, l = pcall(TensorCore.entityList, f) if ok and type(l) == \"table\" then return l end end\n    return nil\n  end\n  -- boss entity (Guardian Arkveld, ContentID 14237, the visible model - not the 9020 helpers)\n  function A.boss()\n    local list = A.ents(\"contentid=14237\")\n    if list then\n      for _, e in pairs(list) do\n        if e.modelid == nil or e.modelid ~= 9020 then return e end\n      end\n    end\n    return nil\n  end\n  function A.myTowerKey()\n    local t = A.cfg.tower\n    if t ~= \"AUTO\" then return t end\n    local s = A.slot()\n    return s and A.SLOT_TOWER[s] or nil\n  end\nend\n-- Towers: countdown on you to each puddle drop and to the soak; ring on your own tower as soon as the towers\n-- appear; arrows for the puddle baits (checked against every logged tower set):\n-- puddle 1 dead centre, puddle 2 9.5y out toward your tower, puddle 3 at the wall clear of every tower,\n-- then into your tower once your puddle 2 has gone off. Steps switch on the real puddle casts (43923).\nlocal T = A.tw\nif not (T and T.t) then return end\nlocal el = (Now() - T.t) / 1000\nif el > 11.4 then return end\nif A.cfg.countdown and AnyoneCore and AnyoneCore.addWorldTextCountdownOnEnt then\n  local p = TensorCore.mGetPlayer()\n  if p then\n    for i, s in ipairs(A.TW_STEP) do\n      if el >= s[1] and el < s[2] and not T.cd[i] then\n        T.cd[i] = true\n        pcall(AnyoneCore.addWorldTextCountdownOnEnt, math.floor((s[2] - el) * 1000), p.id, s[3], true, 1.5, 2)\n      end\n    end\n  end\nend\nif not (T.list and #T.list >= 6) then return end\nlocal key = A.myTowerKey()\nlocal D = key and A.TDIR[key]\nif not D then return end\nlocal best, bs\nfor _, w in ipairs(T.list) do\n  if w.big == D[3] then\n    local s = (w.x - A.CX) * D[1] + (w.z - A.CZ) * D[2]\n    if not bs or s > bs then best, bs = w, s end\n  end\nend\nif not best then return end\nlocal tx, tz = best.x, best.z\nlocal rT = math.max(0.1, math.sqrt((tx - A.CX) ^ 2 + (tz - A.CZ) ^ 2))\nlocal ux, uz = (tx - A.CX) / rT, (tz - A.CZ) / rT\nA.ring(tx, tz, best.big and 4 or 2, 0x33FF33)\nif not A.cfg.towerArrows then return end\n-- step from the puddle casts; fixed times only as a fallback\nlocal set = T.set\nlocal step\nif set then\n  step = (set >= 3 and Now() - T.pT >= 800) and 3 or math.min(set, 2)\nelse\n  step = el < 3.0 and 0 or el < 5.55 and 1 or el < 8.83 and 2 or 3\nend\nif step == 0 then\n  A.goTo(A.CX, A.CZ, 0x00FFFF, 1.0)                               -- puddle 1: dead centre\nelseif step == 1 then\n  A.goTo(A.CX + 9.5 * ux, A.CZ + 9.5 * uz, 0x00FFFF, 1.0)         -- puddle 2: 9.5y out toward your tower\nelseif step == 2 then\n  -- puddle 3: closest wall spot to your tower that is >= 6.5 + radius from every tower\n  if not T.wall then\n    local a0 = math.atan2(ux, uz)\n    for i = 0, 90 do\n      for _, sg in ipairs({1, -1}) do\n        local a = a0 + sg * math.rad(i * 2)\n        local x, z = A.CX + 18.5 * math.sin(a), A.CZ + 18.5 * math.cos(a)\n        local ok = true\n        for _, w in ipairs(T.list) do\n          if math.sqrt((w.x - x) ^ 2 + (w.z - z) ^ 2) < 6.5 + (w.big and 4 or 2) then ok = false break end\n        end\n        if ok then T.wall = {x, z} break end\n      end\n      if T.wall then break end\n    end\n    T.wall = T.wall or {A.CX + 18.5 * ux, A.CZ + 18.5 * uz}\n  end\n  A.goTo(T.wall[1], T.wall[2], 0x0099FF, 1.0)\nelse\n  A.goTo(tx, tz, 0x33FF33, best.big and 1.5 or 1.0)                -- soak\nend\n",
